// ⚠️ 这里曾有一张 RPE_SCALE 表（RPE 8 = "75-85%" / RPE 10 = "100%"），2026-10-30 删除。
// 删它的两个理由：
//  1. 全仓库零引用 —— 只有这一处定义，没有任何地方读它，删掉对线上零影响。
//  2. 口径是错的 —— 它把 RPE 当成了「%1RM 的直接刻度」。RPE 说的是「这一组还剩几次」，
//     不是「这个重量占 1RM 多少」。同一个 80% 1RM：做 3 次 ≈ RPE 7，做 10 次做到力竭 = RPE 10。
//     **不绑定次数，RPE 和 %1RM 就换不了算。**
// 正确且在用的是 rpe-rir.js 的 FB_RPE_SCALE（RPE 8 = 还能再做 2 次），显示给用户看的也是那一套。
//
// ⚠️ 别顺手去改别处的 %1RM —— 那些是对的：getWarmup() 的 40%×10 / 60%×6 / 80%×3，
//    和 CONFIGS 里的 intensity + reps + rpe 三元组，都**写死了次数**，所以 %1RM 是自洽的。
//    有问题的从来只有上面这张孤表。

// 热身组建议
function getWarmup(level, goal) {
  if (goal === "cardio" || goal === "marathon") {
    return {
      type:"run",
      warmup:[
        "关节激活：踝关节绕环、膝关节屈伸、髋关节画圈（各30秒）",
        "动态拉伸：高抬腿30秒 + 后踢腿30秒 + 弓步转体每侧5次",
        "轻松慢跑 5-8 分钟，逐步提升心率"
      ],
      cooldown:[
        "慢跑/快走 5 分钟让心率缓慢下降",
        "静态拉伸（每个动作保持20-30秒）：股四头肌、腘绳肌、小腿、臀肌、髂腰肌",
        "泡沫轴放松：大腿前后侧、小腿、臀部（每个部位30-60秒）"
      ]
    };
  }
  // ⚠️ 力量目标也要有"一般热身"(NSCA 的 RAMP 四段: Raise → Activate → Mobilize → Potentiate)。
  //    以前只给了最后一段 Potentiate(40%→60%→80% 的重量递增组),等于冷身子直接抓杆上手;
  //    反倒是 cardio/marathon 一直有"轻松慢跑 5-8 分钟"这一段 Raise。
  //    页面上「🧤 推荐热身」那块是 Activate/Mobilize(关节活动度),代替不了"先把心率提上来、身体发热"。
  var liftGeneral = [
    "先做 3-5 分钟低强度有氧（快走 / 慢跑 / 椭圆机 / 慢速跳绳），走到微微出汗、身体发热",
    "再活动肩髋踝各 30 秒：肩绕环、髋绕环、踝绕环 —— 关节活动开了再上重量"
  ];
  if (level === "beginner") return {type:"lift", general:liftGeneral, sets:[{s:2, r:"10-15次", i:"空杆/极轻", n:"活动关节，熟悉动作轨迹"}]};
  if (level === "intermediate") return {type:"lift", general:liftGeneral, sets:[
    {s:1, r:"10次", i:"40% 1RM", n:"热身激活"},
    {s:1, r:"6次",  i:"60% 1RM", n:"过渡组"}
  ]};
  return {type:"lift", general:liftGeneral, sets:[
    {s:1, r:"10次", i:"40% 1RM", n:"热身"},
    {s:1, r:"5次",  i:"60% 1RM", n:"过渡"},
    {s:1, r:"3次",  i:"80% 1RM", n:"冲组准备"}
  ]};
}

// ============ 执行幅度提示（拉伸位 / 全程幅度）============
// 由来(v169):近十年的证据(舍恩菲尔德等)—— 在**肌肉被拉长的那一端**受力,肥大效果更好:
//   卧推下放到底 > 半程卧推;弯举完全伸展 > 半程弯举;深蹲蹲到底 > 半蹲。
//   动作库 200+ 条只有「怎么发力」的 tips,通篇没有「走多长」的提示 —— 用户只看到「胸 · 3组 × 10次」。
//   对外一句话口径:**不是练多重,是练多长。**
// 匹配顺序:先按动作名关键词(更准),再按部位兜底。
// ⚠️ _kw 顺序有意义:「腿弯举」必须排在「弯举」前面,否则腿弯举会拿到手臂的「完全伸展」提示。
var FB_ROM_TIPS = {
  _kw: [
    ["腿弯举",                     "勾到最大幅度，在拉长的顶点停半秒"],
    ["卧推|哑铃推|推举|俯卧撑|上斜", "下放到最低点再推起，别只做上半程"],
    ["飞鸟|夹胸|扩胸",              "打开到胸肌有拉伸感再合拢"],
    ["划船",                        "送出去时让背阔肌完全拉开，再往回拉"],
    ["下拉|引体|悬垂",              "下放时手臂完全伸直，让背阔肌拉到最长"],
    ["深蹲|腿举|弓步|蹲",           "蹲到大腿低于水平（或尽可能深），别蹲一半就起"],
    ["硬拉|罗马尼亚|臀桥|后踢|髋",  "下放到腘绳肌/臀部有强拉伸感再起身"],
    ["弯举",                        "下放时手臂完全伸直，二头拉到最长再发力"],
    ["臂屈伸|下压|三头",            "先让三头充分拉长再发力，肘部固定不动"],
    ["侧平举|前平举|平举",          "抬到与肩同高，顶点停半秒再慢放回"],
    ["卷腹|举腿|悬垂抬腿|平板",      "全程慢速控制，别借惯性甩"]
  ],
  腿:   "全程走满，拉长到头的那一下别松劲",
  胸:   "下放到最低点再推起，拉长端最有效",
  背:   "充分伸展后再发力，别急着往回拉",
  肩:   "抬到与肩同高，慢放回到底",
  臂:   "完全伸展后再发力，走满全程",
  核心: "全程慢速控制，别借惯性"
};
// 取某个动作的幅度提示;取不到返回 ''（调用方据此整行不输出，不留空行）
function fbRomTip(ex) {
  if (!ex || !ex.m) return '';
  var n = ex.n || '';
  var kw = FB_ROM_TIPS._kw || [];
  for (var i = 0; i < kw.length; i++) {
    try { if (new RegExp(kw[i][0]).test(n)) return kw[i][1]; } catch (e) {}
  }
  return FB_ROM_TIPS[ex.m] || '';
}

// 周期化：第1周偏移0，第2周偏移1，…，最后一周(减载)与倒数第2周一致
function getWeekOffset(week, totalWeeks) {
  totalWeeks = totalWeeks || 4;
  if (week >= totalWeeks) return Math.max(0, totalWeeks - 2); // 减载周保持与倒数第2周相同动作，只降重量
  return week - 1;
}

// 周期化进度
var WEEK_INFO = [
  {note:"基础适应周 — 重点掌握动作模式，不追求重量", deload:false, weightAdjust:"+0%"},
  {note:"渐进超负荷<span class='term-badge' data-term='progressive'>?</span> — 尝试增加重量 2.5-5kg，保持次数", deload:false, weightAdjust:"+5%"},
  {note:"挑战周 — 继续增加重量或次数，接近力竭", deload:false, weightAdjust:"+10%"},
  // ⚠️ 大减载是 -20% 不是 -30%(v118 改)。原来照搬 -30%, 那本不是为减载设计的数:
  // 它是波浪周期的低谷(峰值周之后自然回落), 被当成"减载该降多少"直接用了 —— 两件事合成一个旋钮。
  // deload 的原则是「砍容量、保强度」: 疲劳主要来自容量, 力量与神经适应靠强度维持。
  // 重量掉到 70%(≈50% 1RM)已跌破有效刺激阈值(约 60-65% 1RM), 那一周是低质量空转 ——
  // 恢复效果一样, 却把动作模式和发力感也一起丢掉。收到 80% 后, 与组数下调叠加的总量
  // 落在 48-60%(主流 deload 建议 40-60%), 且强度仍留在有效区间。
  // ⚠️ note 里的百分比必须等于 100 - |weightAdjust|: 这两句被 renderWeekInfo 渲染在同一行,
  //    写成两个数字用户一眼就看出自相矛盾(v116 修过同款)。
  {note:"减载周（Deload）— 重量降至80%，让身体充分恢复", deload:true, weightAdjust:"-20%"}
];

// ============ 周期强度百分比 → 每组次数台阶(按区间宽度的比例) ============
// 由来: 周期表写「+5%」, 但组数不会动(加 1 组 = +25%, 远超一周爬坡幅度)、
//   重量又只在少数加档周才加(见 planner-core 的 fbPeriodWeekSteps) ——
//   那 5% 落不到任何可见变化上, 用户拿到的是一张空头支票。
//   训练里最小可执行单位是「1 次」, 所以把百分比翻译成次数台阶。
// 为什么是"区间宽度的比例"而不是固定次数(v119 改):
//   "8-10次" 加 2 就填满了, "15-20次" 加 2 才刚起步 —— 同一个 +10% 在两种区间上
//   完全是两回事。按宽度算才一致。台阶 = round((hi-lo) × ratio)。
// 为什么不是容量等价换算: 4组×8次 +5% = +1.6 次, 没法执行。取「宁小不大」:
//   台阶宁可少一步, 也不把一周的爬坡做成 +25%。
var FB_REPS_RATIO_BY_PCT = { 0:0, 5:0.25, 10:0.5, 15:0.5, 20:0.75, 25:0.75, 30:1.0 };
var _FB_REPS_RATIO_KEYS = Object.keys(FB_REPS_RATIO_BY_PCT).map(Number)
  .sort(function(a,b){ return a-b; });
// 自重: 没有重量旋钮, 次数是主要杠杆, 比例上浮。但不取 2 倍 ——
//   +10% 那周还要升变式(见 planner-core 的 BW_NOTE_TEXT), 次数再填满就是双重加码。
//   ×1.5 后 W2 = +2 次, 正好对上 BW_NOTE_TEXT["+5%"] 的「每组次数 +2~3 次」。
var FB_REPS_RATIO_BW_MUL = 1.5;

function fbRepsRatioOf(pct, isBw) {
  var p = Math.abs(parseFloat(pct) || 0);
  var r = 0;
  for (var i = 0; i < _FB_REPS_RATIO_KEYS.length; i++) {
    if (p >= _FB_REPS_RATIO_KEYS[i]) r = FB_REPS_RATIO_BY_PCT[_FB_REPS_RATIO_KEYS[i]];
  }
  if (isBw) r = Math.min(1, r * FB_REPS_RATIO_BW_MUL);
  return r;
}

// 心肺目标4周周期化配置（覆盖 WEEK_INFO 和 goalCfg 中的心肺参数）
// durationPct: 基础 totalDuration 的百分比（0.8 = 减20%）
// hiitRoundsAdjust: 在基础 sets 上的增减（控制 HIIT 组数）
// hiitPerSet: HIIT 每组的工作/休息比例
// intensity: 心率区间
// rpe: RPE 范围
var CARDIO_WEEK_CONFIG = [
  {note:"基础适应周 — 建立有氧基础，保持轻松节奏，感受身体反应", deload:false, weightAdjust:"总量 -20%",
   durationPct:0.8, hiitRoundsAdjust:0, hiitPerSet:"20秒工作 + 40秒休息", intensity:"心率 55-65%", rpe:"RPE 4-5"},
  {note:"渐进递增 — 延长LISS时长，HIIT增加1组，逐步提升心率", deload:false, weightAdjust:"总量 +10%",
   durationPct:1.0, hiitRoundsAdjust:1, hiitPerSet:"30秒工作 + 30秒休息", intensity:"心率 60-75%", rpe:"RPE 5-7"},
  {note:"挑战周 — 提升强度，HIIT工作时间延长，接近极限心率", deload:false, weightAdjust:"总量 +20%",
   durationPct:1.1, hiitRoundsAdjust:1, hiitPerSet:"40秒工作 + 20秒休息", intensity:"心率 70-85%", rpe:"RPE 7-9"},
  {note:"恢复周 — 降低总时长30%，减少HIIT组数，让心肺充分适应", deload:true, weightAdjust:"总量 -30%",
   durationPct:0.7, hiitRoundsAdjust:-1, hiitPerSet:"30秒工作 + 45秒休息", intensity:"心率 55-70%", rpe:"RPE 4-5"}
];

// 按自定义周期长度生成力量类周信息（波浪周期化）
// 结构: 第1周适应 → 每3周爬坡 + 1周半减载(-15%)循环 → 最后一周大减载(-20%)
//                                                                        ^^^^^^
// ⚠️ 这里原来是 -30%, v118 把实际值从 -30% 收到 -20% 但注释没跟着改(v169 对齐)。
//    注释和代码对不上的代价:后面写文案/调参数的人照注释写,就会变成"说一套做一套"。
// 爬坡强度按块递增: 块1 +5/+10/+15 → 块2 +10/+15/+20 → 块3 +15/+20/+25 → 封顶 +30%
// totalWeeks = 3 时: 适应 → 增负荷 → 减载; = 4 时与 WEEK_INFO 完全一致
var _CYCLE_MID_NOTES = [
  "渐进超负荷 — 尝试增加重量 2.5-5kg，保持次数",
  "挑战周 — 继续增加重量或次数，接近力竭",
  "冲击周 — 冲击更大重量，注意动作质量",
  "巅峰周 — 逼近个人极限，务必做好保护"
];
// 半减载周（力量类）：-15%，每块第4周插入；3周周期也用它做轻减载收尾
var _CYCLE_DELOAD_WEEK = {
  note: "半减载周 — 重量降至85%，巩固动作技术，为下个循环蓄力",
  deload: true,
  weightAdjust: "-15%"
};
// 新手档的"巩固周"：顶替紧贴末尾的那次半减载（见 buildCycleWeekInfo 里的 newbie 分支）
// 为什么新手不该排双减载：新手有 8-12 周的线性加重视窗（新手效应），这段时间几乎不需要
//   减载。6 周周期原本是「-15% + -30%」连续两周减量，等于把三分之一的进步窗口直接扔掉。
//   改成巩固周：重量持平、不降，只把动作做扎实，再进最后一周大减载 —— 减载次数不变，
//   但不再是连着两周往回退。
// weightAdjust 写 +0% 只是兜底值:真正用的是"上一周的调整值"(见 buildCycleWeekInfo),
//   写死 +0% 会出现"note 说维持上周、实际从上周的 +15% 掉回基准"这同一行自相矛盾的毛病。
//   巩固 = 不再往上加,但也不往回退 —— 重量和上周一样,把动作做扎实。
var _CYCLE_NEWBIE_HOLD = {
  note: "巩固周 — 重量维持上周，把动作做扎实，下周进入减载收尾",
  deload: false,
  weightAdjust: "+0%",
  // ⚠️ hold: 这周不参与「加档周」候选(v120 加)。巩固的定义就是"不再往上加, 但也不往回退",
  //   而 weightAdjust 为了不和上一周打架沿用了上周的正值(见上面注释) —— 于是它会被
  //   fbPeriodIsStepUpWeek 当成"周期表说要涨强度"的候选, 6 周新手实测第 5 周被选成加档周,
  //   横幅直接打出「巩固周 — 重量维持上周 …… · 本周加重量」两个相反说法。
  //   语义 > 数字: 这里必须显式声明它不加重量。
  hold: true
};
// 长周期(>4周)的第 1 周。短周期能直接复用 WEEK_INFO[0] 的"基础适应周",长周期不能:
//   跨周期时基准回退到上一周期的峰值重量(见 fbCalcNextLoad),12 周周期爬了 11 周之后,
//   新一轮第 1 周就是全周期最重的几周之一 —— 实测 90kg vs 真实 10RM 84.9(RPE 9.2),
//   卡片却写着"重点掌握动作模式、不追求重量",和用户手里的重量直接打架。
//   那周的真实任务是"回到减载前的重量、找回发力感",不是从头学动作。
var _CYCLE_LONG_W1 = {
  note: "基准重建周 — 回到减载前的重量，找回发力感，这周不必冲击新重量",
  // 自重用户那周的 note 走 BW_NOTE_TEXT(按 weightAdjust 取键, 见 planner-core),
  // 那张表里 "+0%" 写的是"基础适应周" —— 长周期第 1 周并不是从头学动作, 必须给自己的说法,
  // 否则同一周两种表述, 又是一处"两个数字"。
  bwNote: "基准重建周 — 回到减载前的难度，找回发力感，这周不必冲新变式",
  deload: false,
  weightAdjust: "+0%"
};
// 半恢复周（心肺类）：总量-15%，时长0.85x；3周周期也用它做轻恢复收尾
var _CYCLE_CARDIO_RECOVERY = {
  note: "恢复周 — 时长与强度回落，让心肺充分适应后继续进阶",
  deload: true,
  weightAdjust: "总量 -15%",
  durationPct: 0.85,
  hiitRoundsAdjust: -1,
  hiitPerSet: "30秒工作 + 40秒休息",
  intensity: "心率 55-70%",
  rpe: "RPE 4-5"
};
// goal 传进来的原因: 马拉松不是"力量的短周期", 它有自己的四期分期, 不能套这张波浪表。
// level 传进来的原因: 新手不排双减载(见 _CYCLE_NEWBIE_HOLD)。周期表和主计划必须是同一张,
//   所以这个判断只能在这里做 —— 放在调用点各算一套, 又会出现"卡上写着减载、实际在爬坡"。
// 不传就是老行为(力量周期), 现有调用点不会因为漏传一个参数就换掉自己的周期表。
function buildCycleWeekInfo(totalWeeks, goal, level) {
  totalWeeks = totalWeeks || 4;
  // 马拉松: 每一周的排布交给 buildMarathonCycleWeekInfo, 长度固定 16
  if (goal === 'marathon' && typeof buildMarathonCycleWeekInfo === 'function') {
    return buildMarathonCycleWeekInfo();
  }
  var isNewbie = (level === 'beginner' || level === '新手' || level === '新手 🌱');
  // 3 周已从 UI 取消(减载占 1/3、峰值只到 +5%,没有渐进超负荷空间)。
  // 这一段留着只是兜底:老存档里 cycleLength 可能还是 3,让它排出一个能用的短周期,
  // 而不是掉进下面的通用逻辑排出个残缺块。
  if (totalWeeks === 3) return [WEEK_INFO[0], WEEK_INFO[1], Object.assign({}, _CYCLE_DELOAD_WEEK)]; // 适应 → 爬坡 → 轻减载
  if (totalWeeks <= 4) return WEEK_INFO.slice(0, totalWeeks);
  var list = [_CYCLE_LONG_W1]; // 第1周:回到减载前基准(不是适应周,见该常量注释)
  var block = 1, posInBlock = 0;
  for (var k = 2; k <= totalWeeks - 1; k++) {
    posInBlock++;
    // 半减载:每块第4周插入。中间块里的半减载后面还有爬坡周,恢复能兑现,保留不动。
    if (posInBlock === 4 && k !== totalWeeks - 1) {
      list.push(Object.assign({}, _CYCLE_DELOAD_WEEK));
      block++; posInBlock = 0;
      continue;
    }
    // 紧贴大减载的那次半减载(= 倒数第2周)不排减载,所有水平都一样。
    // 理由:它后面直接接 -30% 大减载,中间没有一个爬坡周 —— 恢复完立刻又减一次,
    //   这次恢复的收益是零,本质就是连续两周减量,还白占掉一周本来能进阶的训练。
    //   真正的 taper(赛前连续减量)前提是后面有比赛/测试要冲,这里周期结束就进下一轮,没有。
    // 分叉:新手换巩固周(+0%,周期末不该冲峰值);中高级继续爬坡(多拿一周渐进超负荷)。
    if (posInBlock === 4 && k === totalWeeks - 1 && isNewbie) {
      var hold = Object.assign({}, _CYCLE_NEWBIE_HOLD);
      // 维持上周 = 沿用上一周的调整值,而不是写死的 +0%。否则第 4 周 +15%、第 5 周 +0%,
      // 实际降了 15%,卡片却写着"维持上周" —— 用户一对比就发现这行在自相矛盾。
      var prev = list[list.length - 1];
      if (prev && typeof prev.weightAdjust === 'string' && prev.weightAdjust.charAt(0) === '+') {
        hold.weightAdjust = prev.weightAdjust;
      }
      list.push(hold);
      block++; posInBlock = 0;
      continue;
    }
    // 中高级落到这里:posInBlock 保持 4、block 不重置,下面的 boost 自然多上一档
    var boost = Math.min(block * 5 + (posInBlock - 1) * 5, 30);
    // 文案和百分比必须由同一个数驱动。以前 note 取 _CYCLE_MID_NOTES[(posInBlock-1)%4],
    // 每块都重新从"渐进超负荷"开头讲, 而 boost 是跨块累加的 —— N>=7 时第 2/3 块会出现
    // 「渐进超负荷 — 尝试增加重量 2.5-5kg …… 重量调整: +15%」这种同一行自相矛盾的话
    // (renderWeekInfo 把 note 和 weightAdjust 渲染在同一行, 用户直接看得见)。
    // 现在按钮位 → 文案一档: +5%渐进超负荷 / +10%挑战周 / +15%冲击周 / >=+20%巅峰周, 封顶到表尾。
    var noteIdx = Math.min(Math.max(boost / 5 - 1, 0), _CYCLE_MID_NOTES.length - 1);
    list.push({
      note: _CYCLE_MID_NOTES[noteIdx] + "（周期第" + k + "周）",
      deload: false,
      weightAdjust: "+" + boost + "%"
    });
  }
  list.push(WEEK_INFO[3]); // 最后一周:大减载
  return list;
}

// 按自定义周期长度生成心肺类周期配置（波浪周期化，规则同上）
// 每3周爬坡 + 1周恢复(-15%)循环, 最后一周大恢复(-30%)
// 全部参数硬封顶: 心率 ≤85%、HIIT工作 ≤45s、组数调整 ≤+2、时长 ≤1.3x
function buildCardioCycleConfig(totalWeeks) {
  totalWeeks = totalWeeks || 4;
  if (totalWeeks === 3) return [CARDIO_WEEK_CONFIG[0], CARDIO_WEEK_CONFIG[1], Object.assign({}, _CYCLE_CARDIO_RECOVERY)]; // 适应 → 递增 → 轻恢复
  if (totalWeeks <= 4) return CARDIO_WEEK_CONFIG.slice(0, totalWeeks);
  var list = [CARDIO_WEEK_CONFIG[0]]; // 第1周:基础适应
  var block = 1, posInBlock = 0;
  for (var k = 2; k <= totalWeeks - 1; k++) {
    posInBlock++;
    // 半恢复:每块第4周插入;即使落在倒数第2周也插入,与最后一周大恢复组成双减载taper
    if (posInBlock === 4) {
      list.push(Object.assign({}, _CYCLE_CARDIO_RECOVERY));
      block++; posInBlock = 0;
      continue;
    }
    var idx = (block - 1) * 3 + (posInBlock - 1); // 累计爬坡步数(0-based)
    list.push({
      note: (idx === 0 ? "渐进递增 — 延长LISS时长，HIIT增加1组" : "强度攀升 — 继续提升训练量，逼近峰值心率") + "（周期第" + k + "周）",
      deload: false,
      weightAdjust: "+" + Math.min(10 + idx * 5, 40) + "%",
      durationPct: Math.round(Math.min(0.9 + idx * 0.05, 1.3) * 100) / 100,
      hiitRoundsAdjust: Math.min(1 + Math.floor(idx / 2), 2),
      hiitPerSet: Math.min(25 + idx * 5, 45) + "秒工作 + " + Math.max(20, 40 - idx * 2) + "秒休息",
      intensity: "心率 " + Math.min(60 + idx * 3, 78) + "-" + Math.min(75 + idx * 3, 85) + "%",
      rpe: "RPE " + Math.min(5 + idx, 8) + "-" + Math.min(7 + idx, 9)
    });
  }
  list.push(CARDIO_WEEK_CONFIG[3]); // 最后一周:大恢复
  return list;
}

// 马拉松16周训练周期
var MARATHON_PHASES = [
  {name:"基础期", weeks:[1,2,3,4], color:"#F59E0B", desc:"建立有氧基础，每周跑量渐进，以轻松跑+LSD为主"},
  {name:"强化期", weeks:[5,6,7,8], color:"#EF4444", desc:"加入节奏跑和间歇跑，提升乳酸阈值和速度耐力"},
  {name:"巅峰期", weeks:[9,10,11,12], color:"#8B5CF6", desc:"跑量峰值，LSD达到最长距离，模拟比赛配速"},
  {name:"减量期", weeks:[13,14,15,16], color:"#3B82F6", desc:"Taper！跑量降至60%→40%→30%，储备糖原，迎接比赛"}
];
var MARATHON_WEEK_NOTES = {
  1:"轻松跑适应，建立跑步习惯", 2:"增加LSD至初段距离", 3:"保持跑量，感受节奏", 4:"基础期收尾，准备进入强化",
  5:"首次加入节奏跑", 6:"间歇跑入门，提升速度", 7:"跑量继续递增", 8:"强化期峰值，LSD拉长",
  9:"巅峰期开始，跑量最大", 10:"LSD接近目标距离", 11:"模拟比赛配速节奏", 12:"巅峰期收尾，最后一次长距离",
  13:"减量第一周，跑量降至60%", 14:"继续减量，保持轻松跑", 15:"赛前最后一周，跑量30%", 16:"比赛周！放松跑+碳水加载"
};

// 马拉松 16 周专用周期表。
// 以前这里套用的是力量的"每3周爬坡 + 1周半减载"波浪周期, 跟跑步的四期分期毫无血缘关系:
//   第5周  周期表说 -15% 减载, 但 MARATHON_WEEK_NOTES 写的是"首次加入节奏跑"(该加)
//   第15周 周期表说 +25%(全程第二高), 而实际 LSD 从 34km 掉到 14km(-59%), 是最该降的一周
// 同一个 App 里 week-bar 按"基础期/强化期/巅峰期/减量期"分区, P1 卡的柱子却是另一套形状,
// 摆在一起就是自相矛盾。现在这张表直接从 MARATHON_PHASES 派生, 两边说同一件事。
//
// 前 12 周(Ramp): 负荷随周期递增, 增幅逐步收窄 —— 越接近赛前越不该再加量, 这是 taper 的前提。
// 后 4 周(Taper): 不新造口径, 严格沿用 buildMarathonPlan / renderMarathonProgress 里早就写死的
//                 taperRate [0.6, 0.5, 0.4, 0.3] → 跑量降至 60/50/40/30% → -40/-50/-60/-70%。
// 这四周同时标 deload: 减量期本来就是减载, 否则这张表会在"该 taper 的周"告诉别处"这周正常练"。
function buildMarathonCycleWeekInfo() {
  var _ramp = [0, 5, 10, 15, 20, 24, 28, 32, 35, 37, 39, 40];
  var _taper = [0.6, 0.5, 0.4, 0.3];
  var _out = [];
  for (var _w = 1; _w <= 16; _w++) {
    var _ph = null;
    for (var _i = 0; _i < MARATHON_PHASES.length; _i++) {
      if (MARATHON_PHASES[_i].weeks.indexOf(_w) >= 0) { _ph = MARATHON_PHASES[_i]; break; }
    }
    if (!_ph) _ph = MARATHON_PHASES[0];
    var _note = MARATHON_WEEK_NOTES[_w] || '';
    if (_w <= 12) {
      _out.push({
        note: _ph.name + ' · ' + _note + '（第' + _w + '周）',
        deload: false,
        weightAdjust: '+' + _ramp[_w - 1] + '%'
      });
    } else {
      var _k = _w - 13;
      _out.push({
        note: _ph.name + ' · ' + _note + '（第' + _w + '周 · 跑量降至' + Math.round(_taper[_k] * 100) + '%）',
        deload: true,
        weightAdjust: '-' + Math.round((1 - _taper[_k]) * 100) + '%'
      });
    }
  }
  return _out;
}

// 配速计算器
function calcMarathonPaces(targetH, targetM) {
  var totalMin = targetH * 60 + targetM;
  var marathonPace = totalMin / 42.195; // min/km
  function fmt(min){ var m=Math.floor(min), s=Math.round((min-m)*60); return m+":"+(s<10?"0":"")+s; }
  return {
    marathon: fmt(marathonPace),
    easyMin: fmt(marathonPace + 0.75),
    easyMax: fmt(marathonPace + 1.5),
    tempoMin: fmt(marathonPace - 0.25),
    tempoMax: fmt(marathonPace - 0.5),
    interval: fmt(marathonPace - 0.75),
    lsdMin: fmt(marathonPace + 0.5),
    lsdMax: fmt(marathonPace + 1.0)
  };
}

function renderPaceResult() {
  var h = parseInt(document.getElementById('paceH').value) || 4;
  var m = parseInt(document.getElementById('paceM').value) || 30;
  var paces = calcMarathonPaces(h, m);
  // 存储自定义配速，供训练卡片使用
  window._marathonPaces = paces;
  try { localStorage.setItem("fitbuddy_marathon_paces", JSON.stringify(paces)); } catch(e) {}
  // 实时更新训练卡片上的配速显示
  updateMarathonPaceDisplay(paces);
  var rows = [
    {label:"🏁 比赛配速",    val:paces.marathon+"/km"},
    {label:"🟢 轻松跑",     val:paces.easyMin+"-"+paces.easyMax+"/km"},
    {label:"🟡 节奏跑",     val:paces.tempoMin+"-"+paces.tempoMax+"/km"},
    {label:"🔴 间歇跑",     val:paces.interval+"/km"},
    {label:"🔵 LSD长距离",  val:paces.lsdMin+"-"+paces.lsdMax+"/km"}
  ];
  var html = '<div style="background:var(--bg);border-radius:10px;padding:10px 12px;">'+
    '<div style="font-size:13px;font-weight:700;color:var(--text);margin-bottom:6px;">目标完赛 '+h+'小时'+m+'分 → 比赛配速 '+paces.marathon+'/km</div>';
  rows.forEach(function(r){
    html += '<div style="display:flex;justify-content:space-between;padding:4px 0;font-size:12px;border-bottom:1px solid var(--border);">'+
      '<span style="color:var(--text2);">'+r.label+'</span>'+
      '<span style="font-weight:700;color:var(--text);">'+r.val+'</span></div>';
  });
  html += '</div>';
  document.getElementById('paceResult').innerHTML = html;
}

// 将自定义配速更新到训练卡片上
function updateMarathonPaceDisplay(paces) {
  if (!paces) return;
  var cards = document.querySelectorAll('.plan-day');
  cards.forEach(function(card) {
    // 获取训练日名称来判断跑步类型
    var nameEl = card.querySelector('.plan-day-name');
    var dayName = nameEl ? nameEl.textContent : '';
    var exSetEls = card.querySelectorAll('.ex-sets');
    exSetEls.forEach(function(el) {
      if (el.textContent.indexOf('配速') < 0) return;
      var pace;
      if (dayName.indexOf('间歇') >= 0) pace = paces.interval + '/km';
      else if (dayName.indexOf('LSD') >= 0 || dayName.indexOf('长距离') >= 0) pace = paces.lsdMin + '-' + paces.lsdMax + '/km';
      else if (dayName.indexOf('节奏') >= 0) pace = paces.tempoMin + '-' + paces.tempoMax + '/km';
      else if (dayName.indexOf('配速') >= 0) pace = paces.marathon + '/km';
      else pace = paces.easyMin + '-' + paces.easyMax + '/km';
      el.textContent = '\u{1F3C3} 配速 ' + pace;
    });
  });
}

